import java.util.*;class DivideByZeroException extends Exception{DivideByZeroException(){super("Cannot divide by zero");}}public class GuardedCalculator{public static void main(String[]x){Scanner s=new Scanner(System.in);while(true){try{System.out.print("a b operator: ");double a=s.nextDouble(),b=s.nextDouble();String op=s.next();double r=switch(op){case "+"->a+b;case "-"->a-b;case "*"->a*b;case "/"->{if(b==0)throw new DivideByZeroException();yield a/b;}default->throw new IllegalArgumentException("Unknown operator");};System.out.println("Result="+r);break;}catch(InputMismatchException e){System.out.println("Enter valid numbers");s.nextLine();}catch(Exception e){System.out.println(e.getMessage());}finally{System.out.println("Attempt complete");}}}}
